#!/usr/bin/env python3
"""Verify the self-signed development certificate in /app/ssl."""

import datetime
import os
import ssl
import sys

CERT_FILE = "/app/ssl/server.crt"
KEY_FILE = "/app/ssl/server.key"


def decode_cert(path):
    """Return the decoded certificate dict using the stdlib decoder."""
    return ssl._ssl._test_decode_cert(path)


def common_name(cert):
    for rdn in cert.get("subject", ()):
        for key, value in rdn:
            if key == "commonName":
                return value
    return None


def expiry_date(cert):
    # notAfter looks like: 'Nov  1 16:27:56 2027 GMT'
    expires = datetime.datetime.strptime(cert["notAfter"], "%b %d %H:%M:%S %Y %Z")
    return expires.strftime("%Y-%m-%d")


def main():
    # 1. The certificate file must exist.
    if not os.path.isfile(CERT_FILE):
        print(f"ERROR: certificate file not found: {CERT_FILE}")
        return 1

    if not os.path.isfile(KEY_FILE):
        print(f"ERROR: private key file not found: {KEY_FILE}")
        return 1

    # 2. The certificate and key must load (this also checks they match).
    try:
        context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        context.load_cert_chain(certfile=CERT_FILE, keyfile=KEY_FILE)
    except (ssl.SSLError, OSError) as exc:
        print(f"ERROR: failed to load certificate/key: {exc}")
        return 1

    try:
        cert = decode_cert(CERT_FILE)
    except (ssl.SSLError, OSError) as exc:
        print(f"ERROR: failed to decode certificate: {exc}")
        return 1

    cn = common_name(cert)
    expires = expiry_date(cert)
    if not cn:
        print("ERROR: certificate has no Common Name")
        return 1

    print(f"Common Name: {cn}")
    print(f"Expiration Date: {expires}")
    print("Certificate verification successful")
    return 0


if __name__ == "__main__":
    sys.exit(main())
